import{_ as l,l as i,o as a,c as o,v as t,p as n,x as s,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"内核 TCP 实现要点","description":"","frontmatter":{"title":"内核 TCP 实现要点","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kernel-tcp-impl.md","filePath":"cs/kernel-tcp-impl.md","lastUpdated":1789023840000}'),T={name:"cs/kernel-tcp-impl.md"};function A(C,e,_,E,P,f){const r=i("Mermaid");return a(),o("div",null,[e[1]||(e[1]=t('<h1 id="内核-tcp-实现要点" tabindex="-1">内核 TCP 实现要点 <a class="header-anchor" href="#内核-tcp-实现要点" aria-label="Permalink to &quot;内核 TCP 实现要点&quot;">​</a></h1><div class="epigraph"><p>内核 TCP 是套接字上的状态机：发送队列、重传定时器、SACK 块、拥塞窗口与 ACK 处理，全部围着 sk_buff 转。</p><footer>—— 据 RFC 9293；Linux tcp 实现文档；Stevens, <em>TCP/IP Illustrated</em></footer></div><p><a href="/cs/socket-buffers">上一课</a>给了窗口的内存来源。主干网络课若已有拥塞直觉，本课 <strong>不重导 AIMD</strong>。缺口是 OS 落点：哪些队列、哪些定时器、与 <a href="/cs/gro-gso">GSO</a> 如何接头。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>tcp_write_xmit</code> 按 cwnd 与窗口从 <code>sk_write_queue</code> 取 skb。丢失：RTO 或快速重传，SACK 决定重发哪段。时间：RACK 等新路径仍是「估计 RTT、何时断定丢」。缺口：TIME_WAIT、listen 的 SYN 队列与 accept 队列满；小包延迟 ACK 与 Nagle（<code>TCP_NODELAY</code>）。本课不把 BBR 公式展开成论文复述。</p><p><span class="marginnote">tcp_mem 是全机 TCP 内存压力，与单 sk 的 sndbuf 分层。MD5 签名、AO 是安全附件，不是主路径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建立：三次握手，TFO 可选。数据：推 skb，设 RTO，进 qdisc。ACK：删已确认 skb，开窗，cong. 信号。对照 UDP：无这些队列。对照 <a href="/cs/fsync">fsync</a>：TCP 的「完成」是 ACK，不是介质。对照存储 barrier：这里没有 FUA，只有对端状态。</p>',8)),(a(),n(d,null,{default:s(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22send%22%5D%20--%3E%20WQ%5B%22%E5%86%99%E9%98%9F%E5%88%97%22%5D%0A%20%20WQ%20--%3E%20CWND%5B%22%E5%8F%97%20cwnd%20%E4%B8%8E%E7%AA%97%E5%8F%A3%22%5D%0A%20%20CWND%20--%3E%20TX%5B%22TX%20%E8%B7%AF%E5%BE%84%22%5D%0A%20%20ACK%5B%22%E5%85%A5%20ACK%22%5D%20--%3E%20UNA%5B%22%E9%87%8A%E6%94%BE%E5%B7%B2%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20LOSS%5B%22%E4%B8%A2%22%5D%20--%3E%20RTX%5B%22%E9%87%8D%E4%BC%A0%E9%98%9F%E5%88%97%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>内核把 RFC 状态机编成 per-sock 数据，使「可靠字节流」成为系统调用。性能旋钮（窗口缩放、SACK、TSO）都是这个状态机的输入。不要写成 LLM 课的序列模型。与 <a href="/cs/nfs-semantics">NFS</a>：NFS 可跑在 TCP 上，语义裂缝仍在 NFS，不在 TCP 可靠性。</p><p>监听：SYN flood 用 syncookies 换状态，是安全与资源的折中。</p><p>实现上：RACK 用时间而不是重复 ACK 计数判断丢包。listen 的 accept 队列满则握手完成的连接被丢，应用看见的是客户端超时。TIME_WAIT 占用端口，高连接周转要 tw reuse 一类旋钮。 读法上只引用<a href="/cs/socket-buffers">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>内核 TCP 实现要点</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MPTCP 子流的全部。不保证用户态 TCP（TCP 旁路）与内核状态互通。下一课在 IP 层旁路插入过滤与连接跟踪：netfilter。</p><p>版本字段会变，课序钉的是机制对象「内核 TCP 实现要点」，不是某一主线内核的结构体名。 后课默认：TCP 靠写队列、ACK 与定时器实现可靠。包过滤与 conntrack，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内核 TCP：写队列、重传、窗口、拥塞控制接在 sock 上。</li><li>握手队列与 TIME_WAIT 是资源对象。</li><li>netfilter 是下一课。</li><li>出处：RFC 9293；Stevens <em>T/IP Illustrated</em>；Linux net/ipv4/tcp*.c 文档。</li></ul>',11))])}const u=l(T,[["render",A]]);export{m as __pageData,u as default};
